oxy_webhelp_navlinks = {"arch_configure_locations-d39307e8147":{"topics":[{"title":"Archival locations","shortdesc":"<p class=\"shortdesc\">The Archival locations page provides summary information about existing archival         locations.<\/p>","href":"archival\/arch_archival_locations_page.html","attributes":{"data-id":"arch_archival_locations_page"},"menu":{"hasChildren":false},"tocID":"arch_archival_locations_page-d39307e8158","topics":[]},{"title":"Creating a data center archival location","shortdesc":"<p class=\"shortdesc\">Create a data center archival location and associate it with a Rubrik cluster for         archiving data.<\/p>","href":"archival\/arch_dc_creating_an_archival_location.html","attributes":{"data-id":"arch_dc_creating_an_archival_location"},"menu":{"hasChildren":false},"tocID":"arch_dc_creating_an_archival_location-d39307e8169","topics":[]},{"title":"Microsoft Azure archival locations","shortdesc":"<p class=\"shortdesc\">Configure Microsoft Azure archival locations for data center workloads. Setting up an         Azure archival location involves preparing Azure resources and <span class=\"ph\">RSC<\/span>, creating         the archival location, and managing it after creation.<\/p>","href":"archival\/arch_ms_azure_loc.html","attributes":{"data-id":"arch_ms_azure_loc"},"menu":{"hasChildren":false},"tocID":"arch_ms_azure_loc-d39307e8180","next":"arch_ms_azure_loc-d39307e8180"},{"title":"Amazon S3 archival locations","shortdesc":"<p class=\"shortdesc\">Rubrik CDM supports Amazon S3 as an archival location. You can use <span class=\"ph\">RSC<\/span> to create an Amazon S3 archival location.<\/p>","href":"archival\/arch_amazon_s3.html","attributes":{"data-id":"arch_amazon_s3"},"menu":{"hasChildren":false},"tocID":"arch_amazon_s3-d39307e8507","next":"arch_amazon_s3-d39307e8507"},{"title":"Google Cloud Platform archival locations","shortdesc":"<p class=\"shortdesc\">Rubrik CDM supports Google Cloud Platform as an archival location with four storage     classes, regional and multiregional deployments, and enforced immutability.<\/p>","href":"archival\/arch_gcp.html","attributes":{"data-id":"arch_gcp"},"menu":{"hasChildren":false},"tocID":"arch_gcp-d39307e8826","next":"arch_gcp-d39307e8826"},{"title":"NFS archival locations","shortdesc":"<p class=\"shortdesc\">An NFS archival location is storage on an NFS server where you can archive snapshots         from your Rubrik cluster. You must identify a specific location on the NFS server to serve         as the archival location.<\/p>","href":"archival\/arch_nfs.html","attributes":{"data-id":"arch_nfs"},"menu":{"hasChildren":false},"tocID":"arch_nfs-d39307e8974","next":"arch_nfs-d39307e8974"},{"title":"S3-compatible archival locations","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> supports archival locations compatible with standard S3 APIs,         with options for object-level or bucket-level immutability depending on your Rubrik cluster         version.<\/p>","href":"archival\/amazon_s3_comp_archival_loc.html","attributes":{"data-id":"amazon_s3_comp_archival_loc"},"menu":{"hasChildren":false},"tocID":"amazon_s3_comp_archival_loc-d39307e9106","next":"amazon_s3_comp_archival_loc-d39307e9106"},{"title":"QStar tape archive","shortdesc":"<p class=\"shortdesc\">QStar tape archive enables a Rubrik cluster to store data on tape for long-term retention     and regulatory compliance using QStar Archive Manager on a Windows server.<\/p>","href":"archival\/archiving_qstar_tape_archive.html","attributes":{"data-id":"archiving_qstar_tape_archive"},"menu":{"hasChildren":false},"tocID":"archiving_qstar_tape_archive-d39307e9263","next":"archiving_qstar_tape_archive-d39307e9263"}]}};